#include <queue>
#include <iostream>

void process_queue(std::queue<std::string>& q) {
    while (!q.empty()) {
        // Step 1: Access the element safely
        const std::string& item = q.front();
        std::cout << "Processing: " << item << std::endl;

        // Step 2: Remove the element
        q.pop(); 
    }
}

// Note: Never combine access and pop in a single line
